css:
.ms-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.ms-stage canvas { touch-action: none; cursor: grab; }
.ms-stage canvas.holding { cursor: grabbing; }
.ms-out { margin: 0; font-size: 22px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 16px; min-height: 4.8em; }
.ms-facts { display: grid; grid-template-columns: auto 1fr; gap: 8px 14px; margin: 0; font-size: 21px; line-height: 1.5; }
.ms-facts dt { font-weight: 800; color: var(--accent-ink, #8a5a00); }
.ms-facts dd { margin: 0; }
section#tongsci1-3-2-1-1-mass .head.split .pen { font-size: 40px; white-space: normal; max-width: 760px; text-align: right; line-height: 1.15; }

